import assert from 'node:assert/strict';
import test from 'node:test';
import { invoiceTotalWithTax } from '../lib/invoices.js';

const lines = [{ description: 'Item', quantity: 1, unitPriceCents: 10000 }];

test('adds the tax of the customer region', () => {
  assert.equal(invoiceTotalWithTax({ customerId: 'cus_003', lines }), 12000); // EU 20%
  assert.equal(invoiceTotalWithTax({ customerId: 'cus_002', lines }), 10725); // US_CA 7.25%
});

test('charges no tax to wholesale customers', () => {
  assert.equal(invoiceTotalWithTax({ customerId: 'cus_001', lines }), 10000);
  assert.equal(invoiceTotalWithTax({ customerId: 'cus_005', lines }), 10000);
});

test('throws for an unknown customer', () => {
  assert.throws(() => invoiceTotalWithTax({ customerId: 'cus_999', lines }), /Unknown customer/);
});
